const atlasGrid=document.getElementById('atlasGrid'),atlasSearch=document.getElementById('atlasSearch'),atlasRegionButtons=document.getElementById('atlasRegionButtons');let activeAtlasRegion='all';
function renderAtlas(){const q=atlasSearch.value.trim().toLowerCase(),rows=africanAtlas.filter(([country,region,sites])=>(activeAtlasRegion==='all'||region===activeAtlasRegion)&&(!q||`${country} ${sites}`.toLowerCase().includes(q)));atlasGrid.innerHTML=rows.length?rows.map(([country,region,sites])=>`<article class="country-card"><header><h3>${country}</h3><span>${region}</span></header><p>${sites}</p><small>Open country pocketbook →</small></article>`).join(''):'<div class="atlas-empty"><strong>No countries match this search.</strong><p>Clear the search or choose another African region.</p></div>'}
atlasSearch.addEventListener('input',renderAtlas);atlasRegionButtons.addEventListener('click',event=>{const button=event.target.closest('[data-atlas-region]');if(!button)return;activeAtlasRegion=button.dataset.atlasRegion;atlasRegionButtons.querySelectorAll('button').forEach(item=>item.classList.toggle('selected',item===button));renderAtlas()});renderAtlas();
